REPLACE INTO `mata_kuliah` (`id`, `kode`, `nama`, `sks`, `kurikulum`, `deskripsi`, `tipe`, `qr_kaprodi`, `tgl_pengesahan_kaprodi`, `created_at`, `updated_at`, `prodi_id`, `semester`, `prasyarat`, `kategori`, `cdio_skill`) VALUES (1,'RKS-101','Fundamental of Cyber Security',5,'v2 IABEE','<p>Konsep dasar kerahasiaan, integritas, dan ketersediaan data (CIA Triad), jenis-jenis ancaman/serangan siber umum, vektor serangan, serta arsitektur keamanan informasi dasar.  ZZZZZZZZZZZZ</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,1,NULL,'appsec','st'),(2,'RKS-102','Programming and Algorithm',NULL,'v2 IABEE','<p>Pemahaman logika pemrograman mendasar, struktur data, pengondisian, perulangan, serta perancangan algoritma yang efisien menggunakan bahasa pemrograman dasar.</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-07 23:08:36',1,1,NULL,'appsec','pd'),(3,'RKS-103','Linux Fundamental',5,'v2 IABEE','<p>Pengenalan arsitektur OS Linux, navigasi terminal/CLI, manajemen berkas dan hak akses (permissions), pengelolaan proses, serta shell scripting dasar. INI oke update</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,1,NULL,'system','pd'),(4,'RKS-104','Fundamental of Physics',NULL,'v2 IABEE','<p>Prinsip-prinsip fisika terapan yang melandasi perangkat keras komputer, teori gelombang dan sinyal listrik, serta dampaknya pada transmisi data.</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-07 23:20:34',1,1,NULL,'math','st'),(5,'RKS-105','Discrete Mathematics',NULL,'v2 IABEE','Teori logika matematika, logika predikat, teori himpunan, relasi dan fungsi, kombinatorika, serta teori graf yang menjadi fondasi algoritma kriptografi.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,1,NULL,'math','st'),(6,'RKS-106','Pancasila Education',NULL,'v2 IABEE','Pemahaman nilai-nilai etika, kewarganegaraan, ideologi negara, dan implikasi moral serta hukum bagi profesional di bidang teknologi.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,1,NULL,'general','ps'),(7,'RKS-201','Computer System Administration',NULL,'v2 IABEE','Pengelolaan dan konfigurasi server (Windows/Linux), manajemen user & group, otomatisasi tugas administrasi sistem, serta instalasi infrastruktur layanan dasar.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,2,'RKS-103','system','pd'),(8,'RKS-202','Computer Network',NULL,'v2 IABEE','Pemahaman model referensi OSI dan TCP/IP, pengalamatan IP (IPv4/IPv6), subnetting, analisis packet capture, serta prinsip kerja protokol komunikasi dasar.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,2,NULL,'network','pd'),(9,'RKS-212','Windows Fundamental',NULL,'v2 IABEE','<p>Arsitektur mendalam sistem operasi Windows, pengoperasian utilitas internal (Registry, Event Viewer, Task Manager), manajemen hak akses (ACL/icacls), dan skrip PowerShell dasar.</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,2,NULL,'system','pd'),(10,'RKS-204','Calculus',NULL,'v2 IABEE','<p>xfdsfdsfds</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-07 23:30:48',1,2,'RKS-105','math','st'),(11,'RKS-205','Applied Cryptography',NULL,'v2 IABEE','<p>Penerapan praktis algoritma enkripsi simetris dan asimetris, pembuatan digital signature, fungsi hash, serta arsitektur Public Key Infrastructure (PKI).</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-08 15:06:08',1,2,'RKS-105','math','pd'),(12,'RKS-206','Civic Education',NULL,'v2 IABEE','Kesadaran hukum, hak dan kewajiban warga negara, tata kelola pemerintahan, serta tanggung jawab sosial profesional IT dalam menjaga ketahanan nasional siber.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,2,NULL,'general','ps'),(13,'RKS-301','SOC Essential',NULL,'v2 IABEE','<p>Operasional dasar Security Operations Center (SOC), teknik monitoring trafik jaringan real-time, agregasi dan analisis log keamanan (SIEM), serta penanganan awal insiden siber.</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,'RKS-201','network','pd'),(14,'RKS-302','Internetworking',NULL,'v2 IABEE','Konfigurasi dan perancangan jaringan skala menengah/luas, penerapan protokol routing dinamis (RIP, OSPF, BGP), penggunaan VLAN, dan teknik switching terapan.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,'RKS-202','network','pd'),(15,'RKS-303','Network Defender Essentials',NULL,'v2 IABEE','Strategi pertahanan jaringan aktif dan pasif, penyusunan arsitektur perimetris, penerapan Firewall, serta konfigurasi IDS/IPS untuk pencegahan intrusi.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,'RKS-202','network','pd'),(16,'RKS-304','Web Fundamental',NULL,'v2 IABEE','Pengembangan aplikasi berbasis web dasar menggunakan skema client-side (HTML, CSS, JavaScript) dan penyusunan struktur aplikasi web interaktif.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,'RKS-102','appsec','pd'),(17,'RKS-305','DevOps',NULL,'v2 IABEE','Integrasi siklus pengembangan perangkat lunak (development) dan operasional (operations), otomatisasi deployment, pembuatan alur CI/CD, serta kontainerisasi (Docker/Kubernetes).','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,NULL,'devops','pd'),(18,'RKS-306','Bahasa Indonesia',NULL,'v2 IABEE','Tata cara penyusunan karya ilmiah, penulisan laporan teknis formal, dokumentasi proyek, dan etika komunikasi akademis yang baku.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,NULL,'general','st'),(19,'RKS-307','Religious Education',NULL,'v2 IABEE','Pembentukan karakter kepemimpinan, norma moral, etika profesionalisme, dan penerapan nilai spiritual dalam kehidupan bermasyarakat dan dunia kerja.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,3,NULL,'general','ps'),(20,'RKS-401','Web Application Pentest',NULL,'v2 IABEE','Metodologi pengujian penetrasi pada aplikasi web, identifikasi dan eksploitasi kerentanan perangkat lunak berdasarkan standar OWASP Top 10, serta pembuatan rekomendasi perbaikannya.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,'RKS-304','appsec','pd'),(21,'RKS-402','Database Security',NULL,'v2 IABEE','Pengamanan Relational & Non-Relational Database, penerapan enkripsi at-rest/in-transit, kontrol akses granular, pencegahan serangan SQL Injection, dan audit log basis data.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,'RKS-304','appsec','pd'),(22,'RKS-403','DevSecOps',NULL,'v2 IABEE','Penyisipan praktik pengujian dan otomatisasi keamanan (security testing) langsung ke dalam seluruh alur kerja CI/CD (SAST/DAST) sejak tahap awal pengembangan.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,'RKS-305','devops','pd'),(23,'RKS-404','Threat Intelligence Essential',NULL,'v2 IABEE','Pengumpulan, pengolahan, dan analisis indikator kompromi (IoC) serta taktik penyerang (TTPs) untuk memprediksi dan merespons ancaman siber secara proaktif.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,'RKS-301','network','pd'),(24,'RKS-405','Cyber Security Risk and Management',NULL,'v2 IABEE','Kerangka kerja penilaian risiko (Risk Assessment Frameworks), penyusunan matriks dampak dan ancaman, serta analisis mitigasi risiko TI organisasi.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,NULL,'grc','st'),(25,'RKS-406','General English',NULL,'v2 IABEE','Penguatan kemampuan tata bahasa (grammar), membaca teks teknis (reading comprehension), serta kemampuan menyimak teknis dalam konteks bahasa Inggris.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,4,NULL,'general','ce'),(26,'RKS-501','Ethical Hacking',NULL,'v2 IABEE','Tahapan peretasan secara etis (rekonaisans, pemindaian, gaining access, maintaining access), eksploitasi kerentanan sistem terstruktur, serta pembuatan penetration testing report.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,'RKS-401','appsec','pd'),(27,'RKS-502','Mobile Security',NULL,'v2 IABEE','Identifikasi dan pengujian keamanan pada platform mobile (Android/iOS), reverse engineering aplikasi seluler, penanganan kebocoran data, dan manipulasi runtime.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,'RKS-102','appsec','pd'),(28,'RKS-503','Cloud Computing Security',NULL,'v2 IABEE','Prinsip pengamanan infrastruktur komputasi awan (AWS/Azure/GCP), konfigurasi Identity and Access Management (IAM), isolasi workload, dan pengamanan arsitektur multi-tenant.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,'RKS-403','devops','pd'),(29,'RKS-504','Digital Forensic',NULL,'v2 IABEE','<p>Teknik akuisisi data (imaging), identifikasi bukti digital pada RAM/disk/media penyimpanan, rekonstruksi kronologi insiden, dan penyiapan barang bukti berbasis standar legal (chain of custody).</p>','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-09 14:47:47',1,5,'RKS-103, RKS-212','system','pd'),(30,'RKS-505','Business Continuity Management',NULL,'v2 IABEE','Perancangan strategi Business Continuity Plan (BCP) dan Disaster Recovery Plan (DRP) untuk meminimalkan downtime operasional saat terjadi krisis siber.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,'RKS-405','grc','st'),(31,'RKS-506','English Communication',NULL,'v2 IABEE','Pelatihan komunikasi lisan secara profesional, teknik presentasi teknis di depan pemangku kepentingan, dan simulasi diskusi interaktif dalam bahasa Inggris.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,NULL,'general','ce'),(32,'RKS-507','Entrepreneurship',NULL,'v2 IABEE','Perancangan ide bisnis baru, pembentukan startup berbasis teknologi, validasi pasar, penyusunan pitch deck, dan analisis kelayakan keuangan.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,5,NULL,'general','ps'),(33,'RKS-601','Cyber Security Project',NULL,'v2 IABEE','Proyek berbasis tim untuk memecahkan masalah keamanan siber dunia nyata, mencakup tahap audit, perancangan arsitektur keamanan, hingga implementasi solusi.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,NULL,'appsec','tw'),(34,'RKS-602','IoT Security',NULL,'v2 IABEE','Keamanan ekosistem Internet of Things, ekstraksi firmware, analisis protokol komunikasi (MQTT/CoAP), mitigasi serangan tingkat hardware, dan pengamanan komunikasi sensor-cloud.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,'RKS-102','appsec','pd'),(35,'RKS-603','Statistic and Probability',NULL,'v2 IABEE','Pengolahan data statistik kuantitatif, analisis teoretis peluang kejadian, pemodelan data inferensial, serta penerapannya dalam evaluasi sistem.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,NULL,'math','st'),(36,'RKS-604','Cyber Security Law and Ethics',NULL,'v2 IABEE','Pembahasan regulasi dan perundang-undangan hukum siber (seperti UU ITE, UU PDP, GDPR), etika profesi cybersecurity, serta implikasi tanggung jawab hukum.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,NULL,'grc','ps'),(37,'RKS-605','Research Methodology',NULL,'v2 IABEE','Penyusunan metodologi penelitian ilmiah, penentuan research gap, teknik studi literatur, serta pembuatan kerangka kerja penulisan proposal skripsi/tugas akhir.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,NULL,'research','wc'),(38,'RKS-606','Cyber Security Policy and Audit',NULL,'v2 IABEE','Teknik penyusunan dokumen kebijakan keamanan organisasi, pelaksanaan audit berbasis standar ISO/IEC 27001 atau NIST, dan evaluasi tingkat kepatuhan (compliance).','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,'RKS-505','grc','st'),(39,'RKS-607','AI for Cybersecurity',NULL,'v2 IABEE','Penerapan Machine Learning dan algoritma kecerdasan buatan untuk otomatisasi deteksi anomali trafik, analisis perilaku penyerang (UEBA), dan klasifikasi malware.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,6,NULL,'appsec','pd'),(40,'RKS-701','Industrial Internship',NULL,'v2 IABEE','Pelaksanaan kerja praktik lapangan secara langsung di industri/perusahaan mitra untuk menerapkan keterampilan teknis dan profesional siber di lingkungan profesional nyata.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,7,NULL,'research','ps'),(41,'RKS-702','Scientific Writing',NULL,'v2 IABEE','Penyusunan naskah artikel ilmiah berbasis riset, penyesuaian format publikasi jurnal/konferensi teknis, dan etika pengutipan (anti-plagiarism).','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,7,'RKS-605','research','wc'),(42,'RKS-703','Final Project Proposal',NULL,'v2 IABEE','Perancangan awal, penyusunan dokumen latar belakang, metodologi, dan uji sidang proposal untuk riset atau produk Tugas Akhir.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,7,NULL,'research','wc'),(43,'RKS-801','Final Project',NULL,'v2 IABEE','Eksekusi penuh riset ilmiah atau pembangunan produk keamanan siber mandiri, pengujian solusi, pengolahan data hasil riset, serta pengujian pada sidang Tugas Akhir.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,8,'RKS-703','research','tw'),(44,'RKS-802','English for Workspace Communication',NULL,'v2 IABEE','Persiapan bahasa Inggris untuk lingkungan kerja profesional, mencakup simulasi wawancara kerja, penulisan resume/cover letter, dan korespondensi bisnis formal.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,8,NULL,'general','ce'),(45,'RKS-803','Internship Report',NULL,'v2 IABEE','Penyusunan dokumen pertanggungjawaban ilmiah dari hasil magang industri, presentasi laporan, serta evaluasi capaian kinerja dari penyelia kerja.','wajib',NULL,NULL,'2026-08-12 13:47:11','2026-11-06 16:15:28',1,8,'RKS-701','research','wc'),(46,'TEST-999','Mata Kuliah Flash Test',3,'test','','wajib',NULL,NULL,'2026-08-13 17:57:40','2026-08-13 17:57:40',1,NULL,NULL,NULL,NULL),(47,'TEST-888','Flash Cek',3,'test','','wajib',NULL,NULL,'2026-08-13 17:58:06','2026-08-13 17:58:06',1,NULL,NULL,NULL,NULL),(48,