REPLACE INTO `performance_indicator` (`id`, `student_outcome_id`, `pi_code`, `pi_description`, `level`, `created_at`, `updated_at`) VALUES (1,1,'PI-01.1','Menerapkan matematika diskret, probabilitas, dan statistika untuk menyelesaikan persoalan kuantitatif keamanan (ruang kunci, entropi, laju deteksi)',3,'2026-08-12 15:10:15','2026-11-11 10:23:55'),(2,1,'PI-01.2','Menjelaskan mekanisme sistem operasi, jaringan, dan basis data yang menjadi landasan bekerjanya suatu kontrol keamanan',3,'2026-08-12 15:10:15','2026-11-11 10:39:19'),(3,1,'PI-01.3','Memilih primitif kriptografi yang sesuai untuk sasaran keamanan tertentu (kerahasiaan, integritas, non-repudiasi) beserta alasannya',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(4,1,'PI-01.4','Memetakan kontrol keamanan suatu organisasi ke kerangka tata kelola terstandar (ISO 27001, NIST CSF)',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(5,1,'PI-01.5','Menerapkan prinsip-prinsip dasar kriptografi dalam perlindungan data.',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(6,2,'PI-02.1','Mengidentifikasi aset, aktor ancaman, dan permukaan serangan pada sistem yang diberikan',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(7,2,'PI-02.2','Menyusun model ancaman terstruktur (STRIDE, attack tree, MITRE ATT&CK) atas sistem tersebut',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(8,2,'PI-02.3','Mengevaluasi mutu dan relevansi sumber teknis (CVE, advisory, publikasi ilmiah) sebagai landasan analisis',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(9,2,'PI-02.4','Memeringkat risiko teknis menggunakan metode terstandar (CVSS, matriks risiko) dengan justifikasi tiap parameter',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(10,2,'PI-02.5','Menyimpulkan akar penyebab kerentanan berdasarkan rantai bukti analitis, bukan gejala permukaan',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(11,3,'PI-03.1','Merumuskan kebutuhan keamanan (security requirements) yang terukur dari kebutuhan bisnis organisasi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(12,3,'PI-03.2','Merancang arsitektur keamanan berlapis beserta segmentasi dan penempatan kontrolnya',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(13,3,'PI-03.3','Merancang skema identitas, autentikasi, dan otorisasi yang sesuai model ancaman',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(14,3,'PI-03.4','Menerapkan prinsip secure by design dan privacy by design pada rancangan perangkat lunak atau sistem',4,'2026-08-12 15:10:15','2026-11-11 10:28:05'),(15,3,'PI-03.5','Menimbang trade-off rancangan terhadap biaya siklus hidup, konsumsi sumber daya, dan batasan regulasi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(16,4,'PI-04.1','Menelusuri dan mengorganisasikan data dari standar, basis data kerentanan, dan literatur sebagai dasar investigasi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(17,4,'PI-04.2','Merancang prosedur pengujian dengan variabel, kendali, dan kriteria keberhasilan yang eksplisit',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(18,4,'PI-04.3','Melaksanakan pengujian keamanan sesuai metodologi baku (PTES, OWASP WSTG) dan mendokumentasikannya secara dapat direproduksi',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(19,4,'PI-04.4','Mengumpulkan dan memelihara integritas bukti digital beserta chain of custody',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(20,4,'PI-04.5','Menarik kesimpulan dari data per-iterasi (data mentah), bukan semata dari statistik ringkasan',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(21,5,'PI-05.1','Memilih perkakas keamanan yang tepat untuk suatu tujuan beserta alasan penolakan alternatifnya',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(22,5,'PI-05.2','Mengonfigurasi dan mengoperasikan perkakas pemantauan keamanan (SIEM, IDS/IPS, EDR) hingga menghasilkan deteksi yang benar',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(23,5,'PI-05.3','Mengembangkan skrip atau alur kerja otomasi untuk tugas keamanan yang berulang',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(24,5,'PI-05.4','Membangun model prediktif atau simulasi (statistik/ML) untuk mendukung keputusan keamanan',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(25,5,'PI-05.5','Mengevaluasi keterbatasan perkakas yang dipakai: cakupan, false positive/negative, asumsi tersembunyi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(26,6,'PI-06.1','Menganalisis dampak insiden atau kontrol keamanan terhadap perilaku dan kelompok pengguna',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(27,6,'PI-06.2','Mengestimasi dampak ekonomi insiden atau investasi keamanan (kerugian, ROSI)',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(28,6,'PI-06.3','Menilai konsekuensi keselamatan dan kesehatan dari kegagalan keamanan pada sistem siber-fisik atau infrastruktur kritis',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(29,6,'PI-06.4','Mengevaluasi implikasi hukum dan privasi suatu solusi terhadap UU PDP dan regulasi lintas yurisdiksi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(30,6,'PI-06.5','Menilai konsekuensi keberlanjutan solusi keamanan (konsumsi energi komputasi, siklus hidup perangkat)',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(31,7,'PI-07.1','Mematuhi batas ruang lingkup dan otorisasi tertulis dalam setiap kegiatan pengujian keamanan',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(32,7,'PI-07.2','Menerapkan prosedur responsible/coordinated disclosure atas temuan kerentanan',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(33,7,'PI-07.3','Menunjukkan integritas akademik dan profesional melalui atribusi sumber serta pelaporan hasil apa adanya',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(34,7,'PI-07.4','Menampilkan perilaku inklusif dan menghormati keberagaman dalam interaksi profesional',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(35,7,'PI-07.5','Memutuskan sikap atas dilema etika keamanan siber dengan justifikasi merujuk kode etik dan hukum yang berlaku',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(36,8,'PI-08.1','Menuntaskan tanggung jawab individu sesuai lingkup dan tenggat yang disepakati tim',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(37,8,'PI-08.2','Berkontribusi aktif pada pencapaian sasaran bersama serta pembagian beban yang setara',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(38,8,'PI-08.3','Menjalankan peran kepemimpinan: memfasilitasi rapat, mendelegasikan tugas, dan mengambil keputusan tim',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(39,8,'PI-08.4','Mengelola perbedaan pendapat hingga tercapai keputusan yang diterima anggota tim',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(40,8,'PI-08.5','Berkolaborasi secara produktif dengan anggota berlatar disiplin non-keteknikan',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(41,9,'PI-09.1','Menyusun laporan teknis yang terstruktur, mengikuti standar keteknikan dan konvensi sitasi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(42,9,'PI-09.2','Menyampaikan presentasi lisan yang menyesuaikan kedalaman teknis dengan audiens sasaran',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(43,9,'PI-09.3','Menyajikan informasi melalui bentuk grafis: diagram arsitektur, alur, dan visualisasi data',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(44,9,'PI-09.4','Menghasilkan komunikasi lisan dan tertulis dalam bahasa Inggris pada konteks rekayasa keamanan siber',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(45,9,'PI-09.5','Menyesuaikan istilah dan register komunikasi dengan memperhatikan perbedaan budaya dan bahasa lawan bicara',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(46,10,'PI-10.1','Menyusun rencana proyek yang memuat WBS, jadwal, dan tonggak capaian',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(47,10,'PI-10.2','Mengalokasikan sumber daya dan menyusun estimasi biaya proyek beserta dasar perhitungannya',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(48,10,'PI-10.3','Memantau dan mengendalikan kemajuan proyek terhadap rencana dasar, serta mengambil tindakan koreksi',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(49,10,'PI-10.4','Menyusun dan memutakhirkan register risiko proyek beserta rencana mitigasinya',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(50,10,'PI-10.5','Menerapkan manajemen konfigurasi dan pengendalian perubahan pada artefak proyek',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(51,11,'PI-11.1','Mengidentifikasi kesenjangan kompetensi diri dan menyusun rencana belajar yang terjadwal',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(52,11,'PI-11.2','Menguasai teknologi atau perkakas keamanan baru secara mandiri tanpa instruksi formal, dibuktikan melalui unjuk kerja',4,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(53,11,'PI-11.3','Menilai secara kritis kredibilitas dan kemutakhiran sumber informasi teknis terkini',3,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(54,11,'PI-11.4','Merefleksikan hasil belajar mandiri dan menetapkan langkah pengembangan berikutnya',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(55,11,'PI-11.5','Membagikan pengetahuan hasil belajar mandiri kepada sejawat melalui forum atau dokumentasi',2,'2026-08-12 15:10:15','2026-08-12 15:10:15'),(58,15,'PI-01','bisa makan rujak',2,'2026-10-28 06:34:38','2026-10-28 06:34:38');
