REPLACE INTO `student_outcome` (`id`, `so_code`, `so_description`, `is_active`, `created_at`, `updated_at`, `prodi_id`, `created_by`) VALUES (1,'SO1','Menerapkan pengetahuan matematika, ilmu pengetahuan alam, komputasi, dasar-dasar rekayasa, dan spesialisasi keamanan siber sesuai body of knowledge yang diakui secara internasional (CyBOK) pada prosedur, proses, sistem, dan metodologi rekayasa terapan.',1,'2026-08-12 15:10:15','2026-08-13 00:39:44',1,2),(2,'SO2','Menganalisis permasalahan rekayasa keamanan siber broadly-defined melalui identifikasi, penarikan inferensi, perumusan, dan penelusuran serta evaluasi literatur untuk mencapai kesimpulan yang dapat dibuktikan, menggunakan perkakas analitis yang sesuai dengan bidang spesialisasinya.',1,'2026-08-12 15:10:15','2026-08-13 00:40:33',1,2),(3,'SO3','Merancang sistem, komponen, atau proses keamanan siber untuk memenuhi kebutuhan teridentifikasi dalam menyelesaikan permasalahan rekayasa broadly-defined, dengan pertimbangan keselamatan dan kesehatan publik, biaya siklus hidup, net zero carbon, serta aspek sumber daya, budaya, sosial, dan lingkungan.',1,'2026-08-12 15:10:15','2026-08-12 15:38:12',1,2),(4,'SO4','Menginvestigasi permasalahan rekayasa keamanan siber broadly-defined melalui penelusuran, pemilihan, dan pengorganisasian data relevan dari standar, basis data, dan literatur, serta perancangan dan pelaksanaan eksperimen untuk menghasilkan kesimpulan yang sahih.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(5,'SO5','Memanfaatkan sumber daya dan teknologi keamanan siber yang diperlukan, termasuk pemodelan dan prediksi, serta menyikapi keterbatasannya, untuk menyelesaikan permasalahan rekayasa broadly-defined.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(6,'SO6','Mengevaluasi dampak solusi rekayasa keamanan siber terhadap masyarakat, ekonomi, keberlanjutan, keselamatan dan kesehatan, kerangka hukum, serta lingkungan, dalam menyelesaikan permasalahan rekayasa broadly-defined.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(7,'SO7','Mematuhi secara konsisten etika profesi dan norma praktik rekayasa teknologi keamanan siber, termasuk kepatuhan terhadap hukum nasional dan internasional, dengan menghormati keberagaman dan inklusi.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(8,'SO8','Berfungsi secara efektif dalam melaksanakan beragam tugas, baik sebagai individu maupun sebagai anggota atau pemimpin dalam tim yang beragam, inklusif, dan multidisiplin pada berbagai tatanan kerja.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(9,'SO9','Mengomunikasikan aktivitas rekayasa keamanan siber broadly-defined secara efektif dalam bentuk tertulis, lisan, dan grafis, mencakup penggunaan standar keteknikan dan bahasa yang diakui secara internasional, dengan memperhatikan perbedaan budaya, bahasa, dan cara belajar.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(10,'SO10','Menerapkan prinsip manajemen rekayasa pada proyek keamanan siber, baik sebagai anggota maupun pemimpin dalam tim multidisiplin, mencakup perencanaan, pengorganisasian, kepemimpinan, pengoperasian, pengendalian, dan manajemen risiko.',1,'2026-08-12 15:10:15','2026-08-12 15:20:07',1,2),(11,'SO11','Melaksanakan pembelajaran mandiri dan sepanjang hayat serta berpikir kritis dalam menyikapi tuntutan perkembangan teknologi dan isu keamanan siber terkini.',1,'2026-08-12 15:10:15','2026-08-12 15:10:15',1,2),(15,'S01-1','bisa makan',1,'2026-10-28 06:34:29','2026-10-28 06:34:57',3,14);
/*!40000 ALTER TABLE `student_outcome` ENABLE KEYS */;
UNLOCK TABLES;

